<script setup lang="ts">
import { computed, ref } from 'vue';
import type { Analysis, AnalysisSuggestion, Resume } from '../../shared/types';
import AppIcon from './AppIcon.vue';
const props = defineProps<{ analysis: Analysis; resume: Resume; history: Analysis[]; busy?: string }>();
const emit = defineEmits<{ inspect: [suggestion: AnalysisSuggestion]; export: []; history: [analysis: Analysis]; reanalyze: [] }>();
const issueFilter = ref('all');
const visibleIssues = computed(() => props.analysis.issues.filter(issue => issueFilter.value === 'all' || issue.severity === issueFilter.value));
const highIssueCount = computed(() => props.analysis.issues.filter(issue => issue.severity === 'high').length);
const analysisStale = computed(() => props.analysis.resumeRevision !== props.resume.revision);
const formatDate = (date: string) => new Date(date).toLocaleDateString('zh-CN', { month: 'long', day: 'numeric' });
</script>
<template>
  <view class="report-section">
    <view class="flow-section-header"><view><text class="flow-kicker">分析结果</text><text class="flow-section-title">看清问题，逐项改好</text></view><button class="text-button" :disabled="!!busy" @click="emit('reanalyze')" role="button" tabindex="0">重新诊断<AppIcon name="undo" :size="15" /></button></view>
    <view v-if="analysisStale" class="info-banner"><AppIcon name="info" :size="17" /><text>简历已更新，当前报告基于 V{{ analysis.resumeRevision }}，可重新诊断查看变化。</text></view>
<view class="diagnosis-grid"><view class="diagnosis-main"><view class="panel diagnosis-summary"><view class="panel-heading"><text class="panel-title">把精力，放在最值得改的地方</text><view class="tag">{{ analysis.engine === 'bailian' ? 'AI 建议 · 待核实' : '规则诊断' }}</view></view><text class="summary-text">{{ analysis.summary }}</text><view class="summary-meta"><AppIcon name="clock" :size="14" /><text>{{ formatDate(analysis.createdAt) }} · V{{ analysis.resumeRevision }} · {{ analysis.engine === 'bailian' ? analysis.modelRun?.model + ' · 未接入知识库' : '基于原文的表达检查' }}</text></view></view><view class="issues-heading"><text class="panel-title">值得关注的问题 <text class="count-label">{{ analysis.issues.length }}</text></text><view class="segmented"><button :class="{ active: issueFilter === 'all' }" @click="issueFilter = 'all'" role="button" tabindex="0">全部</button><button :class="{ active: issueFilter === 'high' }" @click="issueFilter = 'high'" role="button" tabindex="0">优先修改</button><button :class="{ active: issueFilter === 'medium' }" @click="issueFilter = 'medium'" role="button" tabindex="0">继续完善</button></view></view><view v-if="!visibleIssues.length" class="empty-state compact-empty"><AppIcon name="check" :size="28" /><text class="empty-title">这个分类下，暂时没有待改问题</text><text class="empty-description">表达检查不能代替招聘判断，请结合实际岗位继续核对。</text></view><view v-for="(issue, index) in visibleIssues" :key="issue.id" class="panel issue-card"><view class="issue-top"><view class="issue-number">{{ String(index + 1).padStart(2, '0') }}</view><text class="issue-title">{{ issue.title }}</text><view class="priority-tag" :class="issue.severity">{{ issue.severity === 'high' ? '优先修改' : issue.severity === 'medium' ? '继续完善' : '细节建议' }}</view></view><text class="issue-description">{{ issue.description }}</text><view v-if="issue.evidence" class="evidence-block"><text class="evidence-caption">你的原文</text><text class="evidence-text">“{{ issue.evidence }}”</text></view><view class="issue-advice"><AppIcon name="bulb" :size="17" /><text>{{ issue.suggestion }}</text></view></view>
                <view v-if="analysis.suggestions.length" class="section-heading suggestions-heading"><view><text class="section-title">把建议，变成下一次进步</text><text class="section-description">逐条查看前后对比，确认真实事实，再采纳修改。</text></view></view><view v-for="suggestion in analysis.suggestions" :key="suggestion.id" class="panel suggestion-card"><view class="suggestion-card-main"><view class="suggestion-dot"><AppIcon name="sparkles" :size="17" /></view><view><text class="issue-title">{{ suggestion.title }}</text><text class="suggestion-reason">{{ suggestion.reason }}</text></view></view><button class="button secondary small-button" :disabled="suggestion.applied || !!busy" @click="emit('inspect', suggestion)" role="button" tabindex="0">{{ suggestion.applied ? '已采纳' : '查看并修改' }}<AppIcon :name="suggestion.applied ? 'check' : 'arrow'" :size="15" /></button></view>
              </view><view class="diagnosis-aside"><view class="panel score-panel"><text class="score-panel-title">简历表达参考分</text><view class="score-circle" :style="{ background: `conic-gradient(#0071e3 ${analysis.score * 3.6}deg, #edf0f4 0deg)` }"><view class="score-inner"><text class="score-number">{{ analysis.score }}</text><text class="score-outof">/ 100</text></view></view><text class="score-description">{{ highIssueCount ? `${highIssueCount} 个问题，值得优先关注` : '继续打磨，让表达更完整' }}</text><view class="dimension-list"><view v-for="dimension in analysis.dimensions" :key="dimension.key" class="dimension-item"><view class="dimension-top"><text>{{ dimension.label }}</text><text>{{ dimension.score }}</text></view><view class="dimension-track"><view :style="{ width: `${dimension.score}%` }" /></view></view></view><text class="score-disclaimer">参考分由透明规则计算，不预测录用或 ATS 通过率。</text></view><view v-if="analysis.keywords.matched.length || analysis.keywords.missing.length" class="panel keywords-panel"><text class="panel-title">与岗位相关的表达</text><text class="keyword-caption">简历中已找到（仅文本覆盖）</text><view class="keyword-list"><text v-for="word in analysis.keywords.matched" :key="word" class="keyword matched">{{ word }}</text><text v-if="!analysis.keywords.matched.length" class="subtle">暂无已匹配关键词</text></view><text class="keyword-caption">值得核对补充</text><view class="keyword-list"><text v-for="word in analysis.keywords.missing" :key="word" class="keyword missing">{{ word }}</text><text v-if="!analysis.keywords.missing.length" class="subtle">暂未发现关键词缺口</text></view></view><view class="export-nudge"><AppIcon name="leaf" :size="24" /><text class="export-nudge-title">准备好了，就向前一步。</text><text>把认真准备的经历，交给下一个机会。</text><button class="button secondary full-width" @click="emit('export')" role="button" tabindex="0"><AppIcon name="download" :size="16" />预览与导出</button></view><view v-if="history.length > 1" class="history-list"><text class="field-caption">最近诊断</text><button v-for="item in history.slice(0, 4)" :key="item.id" class="history-item" :class="{ selected: analysis.id === item.id }" @click="emit('history', item)" role="button" tabindex="0"><text>V{{ item.resumeRevision }} · {{ formatDate(item.createdAt) }}</text><text>{{ item.score }} 分</text></button></view></view></view>
  </view>
</template>
